import{_ as e,o as a,c as i,a3 as l}from"./chunks/framework.0RzNNOGV.js";const m=JSON.parse('{"title":"Font family","description":"","frontmatter":{},"headers":[],"relativePath":"faq/font-family.md","filePath":"faq/font-family.md","lastUpdated":1783889029000}'),d={name:"faq/font-family.md"};function s(n,t,o,r,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="font-family" tabindex="-1">Font family <a class="header-anchor" href="#font-family" aria-label="Permalink to “Font family”">​</a></h1><h3 id="how-do-i-make-multiple-fonts-exported-from-glyphr-studio-be-recognizable-as-a-family-in-other-programs" tabindex="-1">How do I make multiple fonts exported from Glyphr Studio be recognizable as a family in other programs? <a class="header-anchor" href="#how-do-i-make-multiple-fonts-exported-from-glyphr-studio-be-recognizable-as-a-family-in-other-programs" aria-label="Permalink to “How do I make multiple fonts exported from Glyphr Studio be recognizable as a family in other programs?”">​</a></h3><p>This was a big challenge over the years, based on a bug in how font files were exported. It was recently fixed (May 2026), so if you follow these simple guidelines, fonts should be recognized as a family:</p><p><strong>On the Settings &gt; Font page</strong> ensure the following for the set of fonts you are wanting to family together:</p><ul><li><code>Font family</code> is the same across all the font files.</li><li><code>Font style</code> is accurate and unique across all the font files.</li><li><code>Font weight</code> is accurate, and corresponds to the Font Style field. To be recognized as the Bold member of a family, set the weight to 700.</li><li><code>Italic angle</code> is accurate, and corresponds to the Font Style field. A non-zero italic angle is what marks a font as Italic/Oblique.</li><li><code>Font stretch</code> is accurate if you are creating condensed or expanded widths (e.g. Condensed, Expanded). Fonts of different widths can now be grouped as one family.</li></ul><p>You can use any descriptive Font style name - including weights like <em>Light</em>, <em>Semibold</em>, or <em>Black</em>, and widths like <em>Condensed</em>. Glyphr Studio automatically writes the underlying font metadata so these group correctly in modern apps while staying compatible with older ones; you don&#39;t need to worry about the technical naming details.</p><p>Figuring out what exactly is looked at to determine a font family took trial and error, so if you encounter a set of fonts that don&#39;t seem to be recognized as a family, please email us at <a href="mailto:mail@glyphrstudio.com" target="_blank" rel="noreferrer">mail@glyphrstudio.com</a> and we can adjust the code to enable it.</p><h3 id="what-can-go-wrong" tabindex="-1">What can go wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to “What can go wrong”">​</a></h3><p>There are many fonts that exist in isolation, without Bold or Italic variations. Word processor apps usually compensate for this by having a built-in capability to do &quot;fake bold&quot; (basically add weight uniformly around shapes) and &quot;fake italic&quot; (just skewing shapes, otherwise known as &#39;oblique&#39;).</p><p>If a set of fonts are properly recognized as a family by your operating system and word processor, trying to bold or italic some text will result in using the other fonts in the family, as opposed to these &quot;fake&quot; variants that are automatically generated.</p><p>Other signs for a set of font files not being recognized as a family is if the individual files are shown as different font choices. In your word processor app&#39;s font menu, they may be listed separately, like:</p><ul><li>Font Name Regular</li><li>Font Name Bold</li><li>Font Name Italic</li></ul><p>As opposed to just seeing &quot;Font Name&quot; with the Bold and Italic variants used when those styles are applied.</p><p>If you are trying to design a font family and are encountering these signs, go back and ensure all the fonts&#39; metadata is correct.</p><p><br><br><br></p><hr><h1 id="way-too-detailed-guidance" tabindex="-1">(Way too) Detailed guidance <a class="header-anchor" href="#way-too-detailed-guidance" aria-label="Permalink to “(Way too) Detailed guidance”">​</a></h1><p>Glyphr Studio handles most of this internally. But if you are curious about the details, the following sections show exactly what metadata needs to correspond in order for a collection of fonts to be interpreted as a family.</p><p>Glyphr Studio does not directly surface all of these font fields, so if you want to go this deep, you&#39;ll have to use some other software to make these granular edits.</p><h3 id="what-makes-multiple-font-files-appear-as-one-family" tabindex="-1">What makes multiple font files appear as one family? <a class="header-anchor" href="#what-makes-multiple-font-files-appear-as-one-family" aria-label="Permalink to “What makes multiple font files appear as one family?”">​</a></h3><p>For OpenType fonts, including both <code>.ttf</code> and <code>.otf</code>, family grouping depends mostly on coordinated metadata in the <code>name</code>, <code>OS/2</code>, <code>head</code>, and sometimes <code>STAT</code> and <code>fvar</code> tables.</p><p>The most important fields are:</p><ul><li><code>name</code> table: <ul><li>Name ID 1: Font Family</li><li>Name ID 2: Font Subfamily</li><li>Name ID 4: Full Font Name</li><li>Name ID 6: PostScript Name</li><li>Name ID 16: Typographic Family</li><li>Name ID 17: Typographic Subfamily</li><li>Name IDs 21/22: WWS Family/Subfamily, when needed</li></ul></li><li><code>OS/2</code> table: <ul><li><code>usWeightClass</code></li><li><code>usWidthClass</code></li><li><code>fsSelection</code></li></ul></li><li><code>head</code> table: <ul><li><code>macStyle</code></li></ul></li><li><code>STAT</code> table: <ul><li>Strongly recommended for modern font families</li><li>Required for variable fonts</li></ul></li><li><code>fvar</code> table: <ul><li>Required for variable fonts</li></ul></li></ul><h3 id="what-is-the-single-most-important-recommendation" tabindex="-1">What is the single most important recommendation? <a class="header-anchor" href="#what-is-the-single-most-important-recommendation" aria-label="Permalink to “What is the single most important recommendation?”">​</a></h3><p>Use <strong>Name ID 16</strong> as the true family name across all related fonts.</p><p>Example:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name ID 16: Acme Sans</span></span></code></pre></div><p>Use this exact same value for:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acme Sans Regular</span></span>
<span class="line"><span>Acme Sans Italic</span></span>
<span class="line"><span>Acme Sans Bold</span></span>
<span class="line"><span>Acme Sans Light</span></span>
<span class="line"><span>Acme Sans Semibold</span></span>
<span class="line"><span>Acme Sans Condensed</span></span>
<span class="line"><span>Acme Sans Display</span></span></code></pre></div><p>Then use <strong>Name ID 17</strong> for each unique style name.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name ID 17: Regular</span></span>
<span class="line"><span>Name ID 17: Bold</span></span>
<span class="line"><span>Name ID 17: Light</span></span>
<span class="line"><span>Name ID 17: Condensed Bold</span></span>
<span class="line"><span>Name ID 17: Display Semibold Italic</span></span></code></pre></div><h3 id="how-should-i-set-legacy-family-names" tabindex="-1">How should I set legacy family names? <a class="header-anchor" href="#how-should-i-set-legacy-family-names" aria-label="Permalink to “How should I set legacy family names?”">​</a></h3><p>Use <strong>Name ID 1</strong> and <strong>Name ID 2</strong> for legacy four-style grouping.</p><p>Legacy Windows and Office-style apps expect a family to contain only:</p><ul><li>Regular</li><li>Bold</li><li>Italic</li><li>Bold Italic</li></ul><p>Recommended pattern:</p><table tabindex="0"><thead><tr><th>Style</th><th>Name ID 1</th><th>Name ID 2</th></tr></thead><tbody><tr><td>Regular</td><td>Acme Sans</td><td>Regular</td></tr><tr><td>Bold</td><td>Acme Sans</td><td>Bold</td></tr><tr><td>Italic</td><td>Acme Sans</td><td>Italic</td></tr><tr><td>Bold Italic</td><td>Acme Sans</td><td>Bold Italic</td></tr><tr><td>Light</td><td>Acme Sans Light</td><td>Regular</td></tr><tr><td>Light Italic</td><td>Acme Sans Light</td><td>Italic</td></tr><tr><td>Semibold</td><td>Acme Sans Semibold</td><td>Regular</td></tr><tr><td>Condensed</td><td>Acme Sans Condensed</td><td>Regular</td></tr><tr><td>Condensed Bold</td><td>Acme Sans Condensed</td><td>Bold</td></tr></tbody></table><p>Do not put values like <code>Light</code>, <code>Semibold</code>, or <code>Condensed</code> in Name ID 2 if maximum Windows/Office compatibility matters.</p><h3 id="how-should-i-set-modern-typographic-names" tabindex="-1">How should I set modern typographic names? <a class="header-anchor" href="#how-should-i-set-modern-typographic-names" aria-label="Permalink to “How should I set modern typographic names?”">​</a></h3><p>Use <strong>Name ID 16</strong> and <strong>Name ID 17</strong> for the real family structure.</p><table tabindex="0"><thead><tr><th>Style</th><th>Name ID 16</th><th>Name ID 17</th></tr></thead><tbody><tr><td>Regular</td><td>Acme Sans</td><td>Regular</td></tr><tr><td>Bold</td><td>Acme Sans</td><td>Bold</td></tr><tr><td>Italic</td><td>Acme Sans</td><td>Italic</td></tr><tr><td>Bold Italic</td><td>Acme Sans</td><td>Bold Italic</td></tr><tr><td>Light</td><td>Acme Sans</td><td>Light</td></tr><tr><td>Light Italic</td><td>Acme Sans</td><td>Light Italic</td></tr><tr><td>Semibold</td><td>Acme Sans</td><td>Semibold</td></tr><tr><td>Condensed</td><td>Acme Sans</td><td>Condensed</td></tr><tr><td>Condensed Bold</td><td>Acme Sans</td><td>Condensed Bold</td></tr></tbody></table><p>Rule of thumb:</p><ul><li>Name ID 16 must be the same for every font in the family.</li><li>Name ID 17 must be unique for every style in that family.</li></ul><h3 id="how-should-i-set-the-full-font-name" tabindex="-1">How should I set the full font name? <a class="header-anchor" href="#how-should-i-set-the-full-font-name" aria-label="Permalink to “How should I set the full font name?”">​</a></h3><p>Use <strong>Name ID 4</strong> as the unique readable full name for each file.</p><p>Examples:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acme Sans</span></span>
<span class="line"><span>Acme Sans Bold</span></span>
<span class="line"><span>Acme Sans Italic</span></span>
<span class="line"><span>Acme Sans Light</span></span>
<span class="line"><span>Acme Sans Semibold</span></span>
<span class="line"><span>Acme Sans Condensed Bold</span></span></code></pre></div><p>Every font file should have a unique Name ID 4.</p><h3 id="how-should-i-set-the-postscript-name" tabindex="-1">How should I set the PostScript name? <a class="header-anchor" href="#how-should-i-set-the-postscript-name" aria-label="Permalink to “How should I set the PostScript name?”">​</a></h3><p>Use <strong>Name ID 6</strong> as a unique machine-safe name.</p><p>Recommended format:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AcmeSans-Regular</span></span>
<span class="line"><span>AcmeSans-Bold</span></span>
<span class="line"><span>AcmeSans-Italic</span></span>
<span class="line"><span>AcmeSans-Light</span></span>
<span class="line"><span>AcmeSans-CondensedBold</span></span></code></pre></div><p>Rules:</p><ul><li>Must be unique per font file</li><li>Use ASCII characters</li><li>Do not use spaces</li><li>Keep it short and stable</li></ul><h3 id="how-should-i-set-weight-and-width" tabindex="-1">How should I set weight and width? <a class="header-anchor" href="#how-should-i-set-weight-and-width" aria-label="Permalink to “How should I set weight and width?”">​</a></h3><p>Set <code>OS/2.usWeightClass</code> to match the visual weight.</p><table tabindex="0"><thead><tr><th>Style</th><th style="text-align:right;">usWeightClass</th></tr></thead><tbody><tr><td>Thin</td><td style="text-align:right;">100</td></tr><tr><td>ExtraLight</td><td style="text-align:right;">200</td></tr><tr><td>Light</td><td style="text-align:right;">300</td></tr><tr><td>Regular</td><td style="text-align:right;">400</td></tr><tr><td>Medium</td><td style="text-align:right;">500</td></tr><tr><td>Semibold</td><td style="text-align:right;">600</td></tr><tr><td>Bold</td><td style="text-align:right;">700</td></tr><tr><td>ExtraBold</td><td style="text-align:right;">800</td></tr><tr><td>Black</td><td style="text-align:right;">900</td></tr></tbody></table><p>Set <code>OS/2.usWidthClass</code> to match the visual width.</p><table tabindex="0"><thead><tr><th>Width</th><th style="text-align:right;">usWidthClass</th></tr></thead><tbody><tr><td>Ultra-condensed</td><td style="text-align:right;">1</td></tr><tr><td>Extra-condensed</td><td style="text-align:right;">2</td></tr><tr><td>Condensed</td><td style="text-align:right;">3</td></tr><tr><td>Semi-condensed</td><td style="text-align:right;">4</td></tr><tr><td>Normal</td><td style="text-align:right;">5</td></tr><tr><td>Semi-expanded</td><td style="text-align:right;">6</td></tr><tr><td>Expanded</td><td style="text-align:right;">7</td></tr><tr><td>Extra-expanded</td><td style="text-align:right;">8</td></tr><tr><td>Ultra-expanded</td><td style="text-align:right;">9</td></tr></tbody></table><h3 id="how-should-i-set-bold-italic-regular-and-oblique-flags" tabindex="-1">How should I set bold, italic, regular, and oblique flags? <a class="header-anchor" href="#how-should-i-set-bold-italic-regular-and-oblique-flags" aria-label="Permalink to “How should I set bold, italic, regular, and oblique flags?”">​</a></h3><p>Coordinate <code>OS/2.fsSelection</code> and <code>head.macStyle</code>.</p><p>Recommended rules:</p><table tabindex="0"><thead><tr><th>Style</th><th style="text-align:right;">usWeightClass</th><th>fsSelection</th><th>head.macStyle</th></tr></thead><tbody><tr><td>Regular</td><td style="text-align:right;">400</td><td>Regular</td><td>none</td></tr><tr><td>Bold</td><td style="text-align:right;">700</td><td>Bold</td><td>Bold</td></tr><tr><td>Italic</td><td style="text-align:right;">400</td><td>Italic</td><td>Italic</td></tr><tr><td>Bold Italic</td><td style="text-align:right;">700</td><td>Bold + Italic</td><td>Bold + Italic</td></tr><tr><td>Light</td><td style="text-align:right;">300</td><td>none, unless Regular in its legacy group</td><td>none</td></tr><tr><td>Semibold</td><td style="text-align:right;">600</td><td>usually none</td><td>usually none</td></tr><tr><td>Oblique</td><td style="text-align:right;">varies</td><td>Oblique</td><td>usually Italic only if legacy compatibility requires it</td></tr></tbody></table><p>Avoid contradictions such as:</p><ul><li>Style name says <code>Italic</code>, but italic bit is not set</li><li>Style name says <code>Bold</code>, but weight is 400</li><li><code>fsSelection</code> says Bold, but <code>head.macStyle</code> does not</li><li>Multiple fonts in the same legacy group marked as Regular</li></ul><h3 id="when-should-i-use-name-ids-21-and-22" tabindex="-1">When should I use Name IDs 21 and 22? <a class="header-anchor" href="#when-should-i-use-name-ids-21-and-22" aria-label="Permalink to “When should I use Name IDs 21 and 22?”">​</a></h3><p>Use <strong>Name IDs 21 and 22</strong> only when you need a WWS grouping fallback.</p><p>WWS means:</p><ul><li>Weight</li><li>Width</li><li>Slope</li></ul><p>Use Name IDs 21/22 when the typographic style includes non-WWS attributes such as:</p><ul><li>Display</li><li>Text</li><li>Caption</li><li>Micro</li><li>Poster</li><li>Optical size</li><li>UI</li></ul><p>Example:</p><table tabindex="0"><thead><tr><th>Style</th><th>Name ID 16</th><th>Name ID 17</th><th>Name ID 21</th><th>Name ID 22</th></tr></thead><tbody><tr><td>Display Bold</td><td>Acme Sans</td><td>Display Bold</td><td>Acme Sans Display</td><td>Bold</td></tr><tr><td>Caption Italic</td><td>Acme Sans</td><td>Caption Italic</td><td>Acme Sans Caption</td><td>Italic</td></tr></tbody></table><p>If the family only varies by weight, width, and italic/oblique, you usually do not need Name IDs 21/22.</p><h3 id="do-i-need-a-stat-table" tabindex="-1">Do I need a STAT table? <a class="header-anchor" href="#do-i-need-a-stat-table" aria-label="Permalink to “Do I need a STAT table?”">​</a></h3><p>Yes, for modern font families, add a correct <code>STAT</code> table whenever possible.</p><p>Use <code>STAT</code> especially if the family includes:</p><ul><li>More than Regular/Bold/Italic/Bold Italic</li><li>Multiple weights</li><li>Multiple widths</li><li>Italics or obliques</li><li>Optical sizes</li><li>Variable fonts</li></ul><p>Recommended STAT axes:</p><table tabindex="0"><thead><tr><th>Axis</th><th>Tag</th></tr></thead><tbody><tr><td>Weight</td><td><code>wght</code></td></tr><tr><td>Width</td><td><code>wdth</code></td></tr><tr><td>Italic</td><td><code>ital</code></td></tr><tr><td>Slant</td><td><code>slnt</code></td></tr><tr><td>Optical Size</td><td><code>opsz</code></td></tr></tbody></table><p>The <code>STAT</code> values should describe each font’s position within the whole family.</p><p>Example for a static Regular font:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wght = 400</span></span>
<span class="line"><span>wdth = 100</span></span>
<span class="line"><span>ital = 0</span></span></code></pre></div><p>Example for Condensed Bold Italic:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wght = 700</span></span>
<span class="line"><span>wdth = 75</span></span>
<span class="line"><span>ital = 1</span></span></code></pre></div><h3 id="what-about-variable-fonts" tabindex="-1">What about variable fonts? <a class="header-anchor" href="#what-about-variable-fonts" aria-label="Permalink to “What about variable fonts?”">​</a></h3><p>For variable fonts, coordinate all normal naming fields plus:</p><ul><li><code>fvar</code> axes</li><li><code>fvar</code> named instances</li><li><code>STAT</code> axis values</li><li>Name ID 25, if needed for variation PostScript names</li></ul><p>Recommended variable axes:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wght</span></span>
<span class="line"><span>wdth</span></span>
<span class="line"><span>ital</span></span>
<span class="line"><span>slnt</span></span>
<span class="line"><span>opsz</span></span></code></pre></div><p>Named instances should have clear names and correct coordinates.</p><p>Example:</p><table tabindex="0"><thead><tr><th>Instance</th><th style="text-align:right;">wght</th><th style="text-align:right;">wdth</th><th style="text-align:right;">ital</th></tr></thead><tbody><tr><td>Regular</td><td style="text-align:right;">400</td><td style="text-align:right;">100</td><td style="text-align:right;">0</td></tr><tr><td>Medium</td><td style="text-align:right;">500</td><td style="text-align:right;">100</td><td style="text-align:right;">0</td></tr><tr><td>Bold</td><td style="text-align:right;">700</td><td style="text-align:right;">100</td><td style="text-align:right;">0</td></tr><tr><td>Condensed</td><td style="text-align:right;">400</td><td style="text-align:right;">75</td><td style="text-align:right;">0</td></tr><tr><td>Condensed Bold</td><td style="text-align:right;">700</td><td style="text-align:right;">75</td><td style="text-align:right;">0</td></tr><tr><td>Italic</td><td style="text-align:right;">400</td><td style="text-align:right;">100</td><td style="text-align:right;">1</td></tr></tbody></table><h3 id="recommended-metadata-pattern" tabindex="-1">Recommended metadata pattern <a class="header-anchor" href="#recommended-metadata-pattern" aria-label="Permalink to “Recommended metadata pattern”">​</a></h3><p>For a family named <code>Acme Sans</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Name ID 1</th><th>Name ID 2</th><th>Name ID 16</th><th>Name ID 17</th><th style="text-align:right;">Weight</th><th style="text-align:right;">Width</th></tr></thead><tbody><tr><td>AcmeSans-Regular.ttf</td><td>Acme Sans</td><td>Regular</td><td>Acme Sans</td><td>Regular</td><td style="text-align:right;">400</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-Bold.ttf</td><td>Acme Sans</td><td>Bold</td><td>Acme Sans</td><td>Bold</td><td style="text-align:right;">700</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-Italic.ttf</td><td>Acme Sans</td><td>Italic</td><td>Acme Sans</td><td>Italic</td><td style="text-align:right;">400</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-BoldItalic.ttf</td><td>Acme Sans</td><td>Bold Italic</td><td>Acme Sans</td><td>Bold Italic</td><td style="text-align:right;">700</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-Light.ttf</td><td>Acme Sans Light</td><td>Regular</td><td>Acme Sans</td><td>Light</td><td style="text-align:right;">300</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-LightItalic.ttf</td><td>Acme Sans Light</td><td>Italic</td><td>Acme Sans</td><td>Light Italic</td><td style="text-align:right;">300</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-Semibold.ttf</td><td>Acme Sans Semibold</td><td>Regular</td><td>Acme Sans</td><td>Semibold</td><td style="text-align:right;">600</td><td style="text-align:right;">5</td></tr><tr><td>AcmeSans-Condensed.ttf</td><td>Acme Sans Condensed</td><td>Regular</td><td>Acme Sans</td><td>Condensed</td><td style="text-align:right;">400</td><td style="text-align:right;">3</td></tr></tbody></table><h3 id="checklist-for-familying-fonts-together" tabindex="-1">Checklist for familying fonts together <a class="header-anchor" href="#checklist-for-familying-fonts-together" aria-label="Permalink to “Checklist for familying fonts together”">​</a></h3><p>Use this checklist when editing font metadata:</p><ul><li>[ ] Set the same Name ID 16 for every font in the intended family</li><li>[ ] Set a unique Name ID 17 for every style</li><li>[ ] Keep Name ID 1/2 compatible with legacy four-style grouping</li><li>[ ] Use only Regular, Bold, Italic, or Bold Italic in Name ID 2</li><li>[ ] Make Name ID 4 unique for every font file</li><li>[ ] Make Name ID 6 unique, ASCII-only, and space-free</li><li>[ ] Set <code>usWeightClass</code> to match the actual weight</li><li>[ ] Set <code>usWidthClass</code> to match the actual width</li><li>[ ] Set <code>fsSelection</code> bold, italic, oblique, and regular bits correctly</li><li>[ ] Keep <code>head.macStyle</code> consistent with <code>fsSelection</code></li><li>[ ] Add a <code>STAT</code> table for modern app compatibility</li><li>[ ] Add <code>fvar</code> named instances for variable fonts</li><li>[ ] Use Name IDs 21/22 only when WWS fallback is needed</li><li>[ ] Validate the fonts after editing</li><li>[ ] Confirm the font license allows modification</li></ul><h3 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to “Common mistakes”">​</a></h3><p>Avoid these mistakes:</p><ul><li>Using different Name ID 16 values across files that should be one family</li><li>Reusing the same Name ID 17 for multiple styles</li><li>Reusing the same Name ID 6 in multiple files</li><li>Putting <code>Light</code>, <code>Semibold</code>, or <code>Condensed</code> in Name ID 2</li><li>Marking multiple files as Regular in the same legacy group</li><li>Setting a style name that disagrees with the weight or italic flags</li><li>Omitting the STAT table from large or modern families</li><li>Treating optical size as weight or width</li><li>Editing commercial fonts without checking the license</li></ul><h3 id="practical-rule" tabindex="-1">Practical rule <a class="header-anchor" href="#practical-rule" aria-label="Permalink to “Practical rule”">​</a></h3><p>If the goal is to make Windows, Office, Canva, Affinity, and similar apps recognize related font files as one family:</p><ol><li>Use Name ID 16 as the shared real family name.</li><li>Use Name ID 17 as the unique style name.</li><li>Keep Name ID 1/2 legacy-safe.</li><li>Make Name ID 4 and Name ID 6 unique.</li><li>Set weight, width, bold, italic, and oblique metadata accurately.</li><li>Add a coherent STAT table.</li><li>Validate the result in multiple apps.</li></ol>`,105)])])}const g=e(d,[["render",s]]);export{m as __pageData,g as default};
